            { "text": "Routing: 121000358", "fontSize": 9, "color": "#475569" },
            { "text": "Account: ****-****-9821", "fontSize": 9, "color": "#475569" },
            { "text": "Status: PENDING", "fontSize": 9, "bold": true, "color": "#ea580c" }
